1	/**
2	 * The Singapore-region "data transmission" map — the centerpiece visual of the
3	 * Singapore VPS hero. A stylized digital map (grid + faint particle field, not
4	 * a literal geographic silhouette) with a glowing Singapore node sending
5	 * curved gradient trails out to APAC city nodes, each labeled with a
6	 * presentational latency figure.
7	 *
8	 * Motion (see the `.sg-*` rules in app/globals.css for the actual keyframes):
9	 *  1. `.sg-trail` — every trail's stroke-dashoffset loops continuously, so the
10	 *     line itself reads as "flowing" outward from Singapore. Pure CSS,
11	 *     supported everywhere.
12	 *  2. `.sg-particle` — a small glowing dot rides the exact same curve via CSS
13	 *     motion-path (`offset-path` + `offset-distance`), progressively
14	 *     enhanced behind `@supports` on top of (1).
15	 *  3. `.sg-node-ring` — a soft expanding/fading ring pulses behind the
16	 *     Singapore node.
17	 * All three are frozen (not hidden) under `prefers-reduced-motion: reduce`.
18	 *
19	 * Deterministic by construction (no Math.random() at render time) so the
20	 * server-rendered markup matches the client on hydration.
21	 */
22	
23	const VB_W = 640;
24	const VB_H = 520;
25	
26	const SINGAPORE = { x: 335, y: 300 };
27	
28	type City = {
29	  name: string;
30	  cc: string;
31	  ms: number;
32	  x: number;
33	  y: number;
34	  /** Quadratic bezier control point for the trail from Singapore to this city. */
35	  cx: number;
36	  cy: number;
37	  /** Which side of the node the label pill sits on, so it never overlaps the trail. */
38	  labelSide: "top" | "bottom" | "left" | "right";
39	};
40	
41	// Positions are stylized, not to scale — but each city sits in roughly the
42	// correct compass direction from Singapore: Malaysia/Indonesia immediately
43	// north/south, Thailand/Vietnam nearby north, India far northwest, Japan far
44	// northeast, Australia far southeast.
45	const CITIES: City[] = [
46	  { name: "Malaysia", cc: "my", ms: 18, x: 313, y: 231, cx: 291, cy: 262, labelSide: "left" },
47	  { name: "Indonesia", cc: "id", ms: 28, x: 300, y: 388, cx: 271, cy: 347, labelSide: "bottom" },
48	  { name: "Thailand", cc: "th", ms: 20, x: 213, y: 193, cx: 200, cy: 254, labelSide: "top" },
49	  { name: "Vietnam", cc: "vn", ms: 22, x: 412, y: 172, cx: 432, cy: 249, labelSide: "top" },
50	  { name: "India", cc: "in", ms: 38, x: 92, y: 203, cx: 142, cy: 268, labelSide: "left" },
51	  { name: "Japan", cc: "jp", ms: 52, x: 556, y: 68, cx: 562, cy: 188, labelSide: "top" },
52	  { name: "Australia", cc: "au", ms: 48, x: 492, y: 472, cx: 472, cy: 408, labelSide: "bottom" },
53	];
54	
55	// Deterministic pseudo-random particle field (mulberry32) — same output on
56	// every render, server and client alike, so hydration never mismatches.
57	function mulberry32(seed: number) {
58	  let a = seed;
59	  return () => {
60	    a |= 0;
61	    a = (a + 0x6d2b79f5) | 0;
62	    let t = Math.imul(a ^ (a >>> 15), 1 | a);
63	    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
64	    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
65	  };
66	}
67	
68	const rand = mulberry32(20260826);
69	const DOTS = Array.from({ length: 46 }, () => ({
70	  x: rand() * VB_W,
71	  y: rand() * VB_H,
72	  r: 0.6 + rand() * 1.3,
73	  o: 0.08 + rand() * 0.22,
74	}));
75	
76	function pathFor(city: City) {
77	  return `M${SINGAPORE.x},${SINGAPORE.y} Q${city.cx},${city.cy} ${city.x},${city.y}`;
78	}
79	
80	const labelOffset: Record<City["labelSide"], { dx: string; dy: string }> = {
81	  top: { dx: "-50%", dy: "calc(-100% - 12px)" },
82	  bottom: { dx: "-50%", dy: "12px" },
83	  left: { dx: "calc(-100% - 12px)", dy: "-50%" },
84	  right: { dx: "12px", dy: "-50%" },
85	};
86	
87	export function SingaporeLatencyMap() {
88	  return (
89	    <div
90	      className="relative aspect-[4/3] w-full overflow-hidden rounded-2xl border border-white/[0.07] bg-navy-950"
91	      role="img"
92	      aria-label="Map of Singapore sending live low-latency connections out to Thailand (20ms), Japan (52ms), India (38ms), Vietnam (22ms), Malaysia (18ms), Indonesia (28ms), and Australia (48ms)"
93	    >
94	      {/* Ambient depth glow behind the whole panel */}
95	      <div
96	        aria-hidden
97	        className="pointer-events-none absolute inset-0"
98	        style={{
99	          background:
100	            "radial-gradient(ellipse 60% 55% at 52% 55%, rgb(111 71 245 / 0.16), transparent 70%), radial-gradient(ellipse 40% 35% at 15% 10%, rgb(59 130 246 / 0.10), transparent 70%)",
101	        }}
102	      />
103	
104	      <svg
105	        viewBox={`0 0 ${VB_W} ${VB_H}`}
106	        className="absolute inset-0 h-full w-full"
107	        preserveAspectRatio="xMidYMid slice"
108	        aria-hidden
109	      >
110	        <defs>
111	          <pattern id="sg-grid" width="32" height="32" patternUnits="userSpaceOnUse">
112	            <path d="M32 0 H0 V32" fill="none" stroke="white" strokeOpacity="0.05" strokeWidth="1" />
113	          </pattern>
114	          <linearGradient id="sg-trail-grad" x1="0%" y1="0%" x2="100%" y2="0%">
115	            <stop offset="0%" stopColor="var(--color-accent-blue)" stopOpacity="0.9" />
116	            <stop offset="100%" stopColor="var(--color-brand-500)" stopOpacity="0.15" />
117	          </linearGradient>
118	          <radialGradient id="sg-node-glow" cx="50%" cy="50%" r="50%">
119	            <stop offset="0%" stopColor="#eaf2ff" stopOpacity="1" />
120	            <stop offset="35%" stopColor="var(--color-accent-blue)" stopOpacity="0.55" />
121	            <stop offset="100%" stopColor="var(--color-brand-500)" stopOpacity="0" />
122	          </radialGradient>
123	        </defs>
124	
125	        {/* Technical grid */}
126	        <rect width={VB_W} height={VB_H} fill="url(#sg-grid)" />
127	
128	        {/* Faint scattered particle field */}
129	        {DOTS.map((d, i) => (
130	          <circle key={i} cx={d.x} cy={d.y} r={d.r} fill="#8fb4ff" opacity={d.o} />
131	        ))}
132	
133	        {/* Trail lines, Singapore outward to each city */}
134	        {CITIES.map((city, i) => (
135	          <path
136	            key={city.name}
137	            d={pathFor(city)}
138	            fill="none"
139	            stroke="url(#sg-trail-grad)"
140	            strokeWidth={1.6}
141	            strokeLinecap="round"
142	            className="sg-trail"
143	            style={{ animationDelay: `${-(i * 0.22)}s` }}
144	          />
145	        ))}
146	
147	        {/* City nodes */}
148	        {CITIES.map((city) => (
149	          <g key={city.name}>
150	            <circle cx={city.x} cy={city.y} r={9} fill="url(#sg-node-glow)" opacity={0.9} />
151	            <circle cx={city.x} cy={city.y} r={2.6} fill="#dbe8ff" />
152	          </g>
153	        ))}
154	
155	        {/* Singapore node — pulsing halo + bright core */}
156	        <circle
157	          cx={SINGAPORE.x}
158	          cy={SINGAPORE.y}
159	          r={10}
160	          fill="none"
161	          stroke="var(--color-accent-blue)"
162	          strokeWidth={1.5}
163	          className="sg-node-ring"
164	        />
165	        <circle cx={SINGAPORE.x} cy={SINGAPORE.y} r={22} fill="url(#sg-node-glow)" />
166	        <circle cx={SINGAPORE.x} cy={SINGAPORE.y} r={5} fill="#ffffff" />
167	
168	        {/* Traveling particles — riding the identical curves via CSS motion-path.
169	            Kept as SVG circles (not HTML) specifically so offset-path resolves in
170	            the same user-space units as the viewBox — an HTML overlay would need
171	            to be pixel-perfect the container's rendered size to line up, which
172	            breaks under responsive scaling; SVG-native stays exact at any size. */}
173	        {CITIES.map((city, i) => (
174	          <circle
175	            key={city.name}
176	            cx={0}
177	            cy={0}
178	            r={3}
179	            fill="#eaf2ff"
180	            className="sg-particle"
181	            style={{
182	              offsetPath: `path("${pathFor(city)}")`,
183	              filter: "drop-shadow(0 0 4px rgba(148,180,255,0.95))",
184	              animationDelay: `${i * 0.34}s`,
185	            }}
186	          />
187	        ))}
188	      </svg>
189	
190	      {/* City labels */}
191	      {CITIES.map((city) => {
192	        const off = labelOffset[city.labelSide];
193	        return (
194	          <div
195	            key={city.name}
196	            className="absolute flex items-center gap-1.5 rounded-full border border-white/10 bg-navy-950/85 px-2.5 py-1 text-[11px] font-medium text-slate-200 shadow-[0_4px_14px_-6px_rgba(0,0,0,0.6)] backdrop-blur-sm"
197	            style={{
198	              left: `${(city.x / VB_W) * 100}%`,
199	              top: `${(city.y / VB_H) * 100}%`,
200	              transform: `translate(${off.dx}, ${off.dy})`,
201	            }}
202	          >
203	            <span>{city.name}</span>
204	            <span className="font-mono text-[10px] font-semibold text-accent-cyan">{city.ms}ms</span>
205	          </div>
206	        );
207	      })}
208	
209	      {/* Singapore label */}
210	      <div
211	        className="absolute flex items-center gap-1.5 rounded-full border border-brand-400/30 bg-navy-950/90 px-3 py-1.5 text-xs font-semibold text-white shadow-[0_6px_18px_-6px_rgba(111,71,245,0.55)]"
212	        style={{
213	          left: `${(SINGAPORE.x / VB_W) * 100}%`,
214	          top: `${(SINGAPORE.y / VB_H) * 100}%`,
215	          transform: "translate(-50%, calc(-100% - 20px))",
216	        }}
217	      >
218	        <img src="/flags/sg.png" width={14} height={11} alt="" className="rounded-[2px] object-cover" />
219	        Singapore
220	      </div>
221	    </div>
222	  );
223	}
