190	  }
191	  /* The sleek, unified "Deploy" CTA used across every service page. Animated
192	     gradient-shift + a one-shot shimmer sweep on hover + an arrow nudge. */
193	  @keyframes btn-deploy-sweep {
194	    0% { transform: translateX(-130%) skewX(-12deg); }
195	    100% { transform: translateX(130%) skewX(-12deg); }
196	  }
197	  .btn-deploy {
198	    @apply relative overflow-hidden rounded-full px-5 text-white;
199	    background-image: linear-gradient(110deg, var(--color-brand-500), var(--color-accent-blue), var(--color-accent-cyan), var(--color-brand-500));
200	    background-size: 220% 100%;
