202	    box-shadow: 0 8px 26px -8px rgb(111 71 245 / 0.55), inset 0 1px 0 0 rgb(255 255 255 / 0.18);
203	    transition: transform 0.2s ease, box-shadow 0.2s ease, background-position 0.6s ease;
204	  }
