206	    transform: translateY(-1px);
207	    background-position: 100% 0;
208	    box-shadow: 0 12px 34px -8px rgb(111 71 245 / 0.7), inset 0 1px 0 0 rgb(255 255 255 / 0.25);
209	  }
210	  .btn-deploy::before {
211	    content: "";
212	    position: absolute;
213	    top: 0;
214	    bottom: 0;
215	    left: 0;
216	    width: 60%;
217	    background: linear-gradient(90deg, transparent, rgb(255 255 255 / 0.38), transparent);
218	    transform: translateX(-130%) skewX(-12deg);
