/**
 * The Singapore-region "data transmission" map — the centerpiece visual of the
 * Singapore VPS hero. A stylized digital map (dense grid + particle field, not
 * a literal geographic silhouette) with a glowing Singapore node sending
 * gradient trails out to APAC country nodes. Country markers are plain text
 * next to a small glowing dot — no pill chips, no flags, no latency figures
 * (per the reference mockup this hero was rebuilt against).
 *
 * Motion (see the `.sg-*` rules in app/globals.css for the actual keyframes):
 *  1. `.sg-trail` — every trail's stroke-dashoffset loops continuously, so the
 *     line itself reads as "flowing" outward from Singapore. Pure CSS,
 *     supported everywhere. A wider, blurred duplicate of the same path rides
 *     underneath (same class, same delay) to give the line a soft glow.
 *  2. `.sg-particle` — a small glowing dot rides the exact same curve via CSS
 *     motion-path (`offset-path` + `offset-distance`), progressively
 *     enhanced behind `@supports` on top of (1).
 *  3. `.sg-node-ring` — two soft expanding/fading rings (staggered) pulse
 *     behind the Singapore node, plus a large static blurred halo for depth.
 * All are frozen (not hidden) under `prefers-reduced-motion: reduce`.
 *
 * Deterministic by construction (no Math.random() at render time) so the
 * server-rendered markup matches the client on hydration.
 */

const VB_W = 760;
const VB_H = 580;

// Positioned lower-center-right of the visual zone, per the reference — the
// floating server card occupies the upper-left, so trails read as flowing
// out and down from behind/beside it.
const SINGAPORE = { x: 460, y: 350 };

type City = {
  name: string;
  x: number;
  y: number;
  /** Quadratic bezier control point for the trail from Singapore to this city. */
  cx: number;
  cy: number;
  /** Which side of the node the label sits on, so it never overlaps the trail. */
  labelSide: "top" | "bottom" | "left" | "right";
};

// Positions are stylized, not to scale — but each city sits in roughly the
// correct compass direction from Singapore: Thailand/Vietnam north, India far
// northwest, Japan/Taiwan far northeast, Australia southeast.
const CITIES: City[] = [
  { name: "Thailand", x: 232, y: 138, cx: 300, cy: 224, labelSide: "top" },
  { name: "India", x: 78, y: 228, cx: 172, cy: 274, labelSide: "left" },
  { name: "Vietnam", x: 392, y: 186, cx: 422, cy: 258, labelSide: "top" },
  { name: "Japan", x: 622, y: 68, cx: 566, cy: 176, labelSide: "top" },
  { name: "Taiwan", x: 696, y: 182, cx: 614, cy: 236, labelSide: "right" },
  { name: "Australia", x: 642, y: 500, cx: 566, cy: 432, labelSide: "bottom" },
];

// Deterministic pseudo-random particle field (mulberry32) — same output on
// every render, server and client alike, so hydration never mismatches.
function mulberry32(seed: number) {
  let a = seed;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const rand = mulberry32(20260826);
// Dense field with two size classes, so the panel reads as a rich, deliberate
// dot texture rather than a sparse scatter.
const DOTS = Array.from({ length: 130 }, (_, i) => ({
  x: rand() * VB_W,
  y: rand() * VB_H,
  r: i % 5 === 0 ? 1.3 + rand() * 1.1 : 0.5 + rand() * 0.7,
  o: i % 5 === 0 ? 0.16 + rand() * 0.22 : 0.06 + rand() * 0.14,
}));

function pathFor(city: City) {
  return `M${SINGAPORE.x},${SINGAPORE.y} Q${city.cx},${city.cy} ${city.x},${city.y}`;
}

const labelOffset: Record<City["labelSide"], { dx: string; dy: string }> = {
  top: { dx: "-50%", dy: "calc(-100% - 10px)" },
  bottom: { dx: "-50%", dy: "10px" },
  left: { dx: "calc(-100% - 10px)", dy: "-50%" },
  right: { dx: "10px", dy: "-50%" },
};

export function SingaporeNetworkMap() {
  return (
    <div
      className="pointer-events-none relative h-full w-full"
      role="img"
      aria-label="Map of Singapore sending live low-latency network connections out to Thailand, India, Vietnam, Japan, Taiwan, and Australia"
    >
      {/* Ambient depth glow behind the whole panel — stronger/wider than a flat
          background so the graphic reads as radiant rather than a printed
          diagram (deliberately richer than the first pass of this hero). */}
      <div
        aria-hidden
        className="pointer-events-none absolute inset-0"
        style={{
          background:
            "radial-gradient(ellipse 62% 58% at 60% 60%, rgb(111 71 245 / 0.24), transparent 72%), radial-gradient(ellipse 45% 40% at 12% 8%, rgb(59 130 246 / 0.14), transparent 72%), radial-gradient(ellipse 40% 45% at 88% 85%, rgb(59 130 246 / 0.10), transparent 70%)",
        }}
      />

      <svg
        viewBox={`0 0 ${VB_W} ${VB_H}`}
        className="absolute inset-0 h-full w-full"
        preserveAspectRatio="xMidYMid slice"
        aria-hidden
      >
        <defs>
          <pattern id="sg-grid" width="30" height="30" patternUnits="userSpaceOnUse">
            <path d="M30 0 H0 V30" fill="none" stroke="white" strokeOpacity="0.05" strokeWidth="1" />
          </pattern>
          <linearGradient id="sg-trail-grad" x1="0%" y1="0%" x2="100%" y2="0%">
            <stop offset="0%" stopColor="var(--color-accent-blue)" stopOpacity="0.95" />
            <stop offset="100%" stopColor="var(--color-brand-500)" stopOpacity="0.15" />
          </linearGradient>
          <radialGradient id="sg-node-glow" cx="50%" cy="50%" r="50%">
            <stop offset="0%" stopColor="#eef4ff" stopOpacity="1" />
            <stop offset="35%" stopColor="var(--color-accent-blue)" stopOpacity="0.55" />
            <stop offset="100%" stopColor="var(--color-brand-500)" stopOpacity="0" />
          </radialGradient>
          <radialGradient id="sg-node-halo" cx="50%" cy="50%" r="50%">
            <stop offset="0%" stopColor="var(--color-brand-400)" stopOpacity="0.45" />
            <stop offset="100%" stopColor="var(--color-brand-500)" stopOpacity="0" />
          </radialGradient>
          <filter id="sg-blur-sm" x="-60%" y="-60%" width="220%" height="220%">
            <feGaussianBlur stdDeviation="3.4" />
          </filter>
          <filter id="sg-blur-lg" x="-120%" y="-120%" width="340%" height="340%">
            <feGaussianBlur stdDeviation="18" />
          </filter>
        </defs>

        {/* Technical grid */}
        <rect width={VB_W} height={VB_H} fill="url(#sg-grid)" />

        {/* Dense scattered particle field */}
        {DOTS.map((d, i) => (
          <circle key={i} cx={d.x} cy={d.y} r={d.r} fill="#8fb4ff" opacity={d.o} />
        ))}

        {/* Soft blurred glow duplicate of every trail, riding underneath the
            crisp line so the curve reads as luminous rather than flat. */}
        {CITIES.map((city, i) => (
          <path
            key={`glow-${city.name}`}
            d={pathFor(city)}
            fill="none"
            stroke="var(--color-accent-blue)"
            strokeWidth={5}
            strokeOpacity={0.35}
            strokeLinecap="round"
            filter="url(#sg-blur-sm)"
            className="sg-trail"
            style={{ animationDelay: `${-(i * 0.22)}s` }}
          />
        ))}

        {/* Crisp trail lines, Singapore outward to each city */}
        {CITIES.map((city, i) => (
          <path
            key={city.name}
            d={pathFor(city)}
            fill="none"
            stroke="url(#sg-trail-grad)"
            strokeWidth={1.8}
            strokeLinecap="round"
            className="sg-trail"
            style={{ animationDelay: `${-(i * 0.22)}s` }}
          />
        ))}

        {/* City nodes */}
        {CITIES.map((city) => (
          <g key={city.name}>
            <circle cx={city.x} cy={city.y} r={10} fill="url(#sg-node-glow)" opacity={0.85} />
            <circle cx={city.x} cy={city.y} r={2.8} fill="#e6efff" />
          </g>
        ))}

        {/* Singapore node — large blurred halo, two staggered pulsing rings,
            bright core. The clear visual anchor of the whole graphic. */}
        <circle cx={SINGAPORE.x} cy={SINGAPORE.y} r={46} fill="url(#sg-node-halo)" filter="url(#sg-blur-lg)" />
        <circle
          cx={SINGAPORE.x}
          cy={SINGAPORE.y}
          r={11}
          fill="none"
          stroke="var(--color-accent-blue)"
          strokeWidth={1.6}
          className="sg-node-ring"
        />
        <circle
          cx={SINGAPORE.x}
          cy={SINGAPORE.y}
          r={11}
          fill="none"
          stroke="var(--color-brand-400)"
          strokeWidth={1.4}
          className="sg-node-ring"
          style={{ animationDelay: "-1.3s" }}
        />
        <circle cx={SINGAPORE.x} cy={SINGAPORE.y} r={26} fill="url(#sg-node-glow)" />
        <circle cx={SINGAPORE.x} cy={SINGAPORE.y} r={5.5} fill="#ffffff" />

        {/* Traveling particles — riding the identical curves via CSS motion-path.
            Kept as SVG circles (not HTML) specifically so offset-path resolves in
            the same user-space units as the viewBox — an HTML overlay would need
            to be pixel-perfect the container's rendered size to line up, which
            breaks under responsive scaling; SVG-native stays exact at any size. */}
        {CITIES.map((city, i) => (
          <circle
            key={city.name}
            cx={0}
            cy={0}
            r={3.2}
            fill="#eaf2ff"
            className="sg-particle"
            style={{
              offsetPath: `path("${pathFor(city)}")`,
              filter: "drop-shadow(0 0 5px rgba(148,180,255,0.95))",
              animationDelay: `${i * 0.34}s`,
            }}
          />
        ))}
      </svg>

      {/* City labels — plain text next to the glowing dot, no chip/flag/latency. */}
      {CITIES.map((city) => {
        const off = labelOffset[city.labelSide];
        return (
          <div
            key={city.name}
            className="absolute whitespace-nowrap text-[13px] font-medium text-slate-200"
            style={{
              left: `${(city.x / VB_W) * 100}%`,
              top: `${(city.y / VB_H) * 100}%`,
              transform: `translate(${off.dx}, ${off.dy})`,
              textShadow: "0 2px 8px rgba(0,0,0,0.65)",
            }}
          >
            {city.name}
          </div>
        );
      })}

      {/* Singapore label — bold white, directly beneath the central node. */}
      <div
        className="absolute whitespace-nowrap text-base font-bold text-white"
        style={{
          left: `${(SINGAPORE.x / VB_W) * 100}%`,
          top: `${(SINGAPORE.y / VB_H) * 100}%`,
          transform: "translate(-50%, 22px)",
          textShadow: "0 2px 12px rgba(0,0,0,0.7)",
        }}
      >
        Singapore
      </div>
    </div>
  );
}

/**
 * The stat strip beneath the Singapore hero — six equal columns separated by
 * thin vertical dividers, each a small icon above a bold stat and a smaller
 * gray caption. Purely presentational; figures mirror the same "~47s deploy /
 * 99.9% uptime" claims used elsewhere on the marketing site (LiveServerCard,
 * page copy), not a live data source.
 */

const iconCls = "h-6 w-6 text-accent-blue";

function BoltIcon() {
  return (
    <svg viewBox="0 0 24 24" fill="none" className={iconCls} aria-hidden>
      <path d="M12.9 3 5.4 13.2h4.9L10.6 21l7.9-10.8h-5.1L12.9 3Z" stroke="currentColor" strokeWidth="1.6" strokeLinejoin="round" />
    </svg>
  );
}
function ShieldIcon() {
  return (
    <svg viewBox="0 0 24 24" fill="none" className={iconCls} aria-hidden>
      <path d="M12 3.5l7.5 3.4v5c0 4.6-3.1 8.4-7.5 9.6-4.4-1.2-7.5-5-7.5-9.6v-5L12 3.5Z" stroke="currentColor" strokeWidth="1.6" strokeLinejoin="round" />
      <path d="M9 12.2l2.1 2.1L15.3 10" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}
function StorageIcon() {
  return (
    <svg viewBox="0 0 24 24" fill="none" className={iconCls} aria-hidden>
      <ellipse cx="12" cy="6" rx="8" ry="3" stroke="currentColor" strokeWidth="1.6" />
      <path d="M4 6v12c0 1.66 3.58 3 8 3s8-1.34 8-3V6" stroke="currentColor" strokeWidth="1.6" />
      <path d="M4 12c0 1.66 3.58 3 8 3s8-1.34 8-3" stroke="currentColor" strokeWidth="1.6" />
    </svg>
  );
}
function GlobeIcon() {
  return (
    <svg viewBox="0 0 24 24" fill="none" className={iconCls} aria-hidden>
      <circle cx="12" cy="12" r="8.25" stroke="currentColor" strokeWidth="1.6" />
      <path d="M3.75 12h16.5M12 3.75c2.2 2.4 3.3 5.2 3.3 8.25S14.2 17.85 12 20.25C9.8 17.85 8.7 15.05 8.7 12S9.8 6.15 12 3.75Z" stroke="currentColor" strokeWidth="1.6" />
    </svg>
  );
}
function ShieldCheckIcon() {
  return (
    <svg viewBox="0 0 24 24" fill="none" className={iconCls} aria-hidden>
      <path d="M12 3.5l7.5 3.4v5c0 4.6-3.1 8.4-7.5 9.6-4.4-1.2-7.5-5-7.5-9.6v-5L12 3.5Z" stroke="currentColor" strokeWidth="1.6" strokeLinejoin="round" />
      <circle cx="12" cy="12" r="3.1" stroke="currentColor" strokeWidth="1.5" />
    </svg>
  );
}
function HeadsetIcon() {
  return (
    <svg viewBox="0 0 24 24" fill="none" className={iconCls} aria-hidden>
      <path d="M4 13v-1a8 8 0 0 1 16 0v1" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" />
      <rect x="3" y="13" width="4" height="6" rx="1.5" stroke="currentColor" strokeWidth="1.6" />
      <rect x="17" y="13" width="4" height="6" rx="1.5" stroke="currentColor" strokeWidth="1.6" />
      <path d="M19 19v.5a3 3 0 0 1-3 3h-2.5" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" />
    </svg>
  );
}

const STATS = [
  { icon: <BoltIcon />, value: "~47s", label: "Average deployment" },
  { icon: <ShieldIcon />, value: "99.9%", label: "Uptime SLA" },
  { icon: <StorageIcon />, value: "NVMe + ZFS", label: "Enterprise storage" },
  { icon: <GlobeIcon />, value: "10Gbps+", label: "Network" },
  { icon: <ShieldCheckIcon />, value: "DDoS Protection", label: "Included" },
  { icon: <HeadsetIcon />, value: "24/7", label: "Expert support" },
];

export function SingaporeStatStrip() {
  return (
    <div className="rail pb-16 sm:pb-20 lg:pb-24">
      <div className="grid grid-cols-2 divide-y divide-white/[0.06] rounded-2xl border border-white/[0.07] bg-navy-900/50 sm:grid-cols-3 sm:divide-y-0 sm:divide-x lg:grid-cols-6">
