import Link from "next/link";
import type { PlanCard } from "@/components/marketing/PricingGrid";
import { LiveServerCard } from "./LiveServerCard";
import { SingaporeNetworkMap } from "./SingaporeNetworkMap";

/**
 * Singapore VPS hosting hero — v5, rebuilt to match an exact reference mockup
 * pixel-for-pixel in composition, copy, and iconography (see PR description /
 * commit messages for the reference), scoped to the hero only. Swapped in for
 * just the top of app/(marketing)/singapore-vps-hosting/page.tsx in place of
 * the shared <PageHero> from UseCaseLanding.
 */

const BULLETS = ["Full root access", "NVMe + ZFS Storage", "Dedicated IPv4", "DDoS Protection", "Instant deployment"];

