import { chromium } from "playwright";

const BASE = "http://127.0.0.1:3847";
const URL = BASE + "/singapore-vps-hosting";

async function shoot(viewport, outPath, waitExtraMs = 1200) {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport });
  await page.goto(URL, { waitUntil: "networkidle", timeout: 60000 });
  await new Promise((r) => setTimeout(r, waitExtraMs));
  await page.screenshot({ path: outPath, fullPage: false });
  await browser.close();
  console.log("saved", outPath);
}

const mode = process.argv[2];
if (mode === "desktop") {
  await shoot({ width: 1440, height: 1000 }, process.argv[3]);
} else if (mode === "mobile") {
  await shoot({ width: 390, height: 844 }, process.argv[3]);
} else {
  console.error("usage: node shoot.mjs desktop|mobile <outpath>");
  process.exit(1);
}

