import { chromium } from "playwright";

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1440, height: 1000 } });
const msgs = [];
page.on("console", (m) => msgs.push(`[console:${m.type()}] ${m.text()}`));
page.on("pageerror", (e) => msgs.push(`[pageerror] ${e.message}`));
await page.goto("http://127.0.0.1:3847/singapore-vps-hosting", { waitUntil: "networkidle", timeout: 60000 });
await new Promise((r) => setTimeout(r, 1500));
console.log(msgs.length ? msgs.join("\n") : "NO_CONSOLE_MESSAGES");
await browser.close();

import { chromium } from "playwright";

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
await page.goto("http://127.0.0.1:3847/singapore-vps-hosting", { waitUntil: "networkidle", timeout: 60000 });
await new Promise((r) => setTimeout(r, 800));
const gotIt = page.getByRole("button", { name: "Got it" });
if (await gotIt.isVisible().catch(() => false)) {
  await gotIt.click();
  await new Promise((r) => setTimeout(r, 400));
}
await page.screenshot({ path: process.argv[2], fullPage: true });
console.log("saved full-page", process.argv[2]);
await browser.close();
